import ajax from "@/utils/ajax";
import { Message, Modal } from "@arco-design/web-react";
import { action, computed, observable, runInAction, makeObservable } from "mobx";
import file from "@/store/file";
import React from "react";



class Store {

    @observable list = [];

    @action setList = (list: any[]) => {
        this.list = list;
    }

    @observable editData: any = null;
    @action setEditData = (data) => {
        this.editData = data;
    }
    @observable visible = false;
    @action setVisible = (bool) => {
        this.visible = bool;
    }


    // 获取图标列表
    getList = async () => {

    }


    constructor() {
        makeObservable(this);
    }


    @computed get title(){
        return this.editData? `图片编辑` : `图片上传`
    }

    @observable compress = true;    // 是否压缩
    @action setCompress = (bool) => {
        this.compress = bool;
    }
    @observable maxWidth = 1028;    // 最大宽度
    @action setMaxWidth = (val) => {
        this.maxWidth = val;
    }
    @observable quality = 0.7;      // 压缩精度
    @action setQuality = (num) => {
        this.quality = num;
    }


    @observable fileName = "";
    @action setFileName = (val) => {
        this.fileName = val;
    }

    @observable name = "";
    @action setName = (val) => {
        this.name = val;
    }





    // 删除图标
    deleteFile(data: any){
        Modal.confirm({
            title: "删除确认",
            content: `请确认是否要删除 ${data.fileName} 图标`,
            onOk: () => {

            }
        })
    }

}


export default Store;